
Object.assign(window.ISLAMA_EMBED,{
"aa-desert.webp":"data:image/webp;base64,",
"aa-map.webp":"data:image/webp;base64,",
"aa-nomads.webp":"data:image/webp;base64,",
"aa-coast.webp":"data:image/webp;base64,",
"aa-uzza.webp":"data:image/webp;base64,",
"aa-lat.webp":"data:image/webp;base64,",
"aa-manat.webp":"data:image/webp;base64,"
});
(() => {
 'use strict';
 const ref = window.ISLAMA_EMBED || {};
 const image = (name) => ref[name] || '';
 const questions = [
   { stage:1, prompt:'Non dago Arabiar penintsula?', answer:'arabia',tip:'Itsaso Gorriaren eta Persiako golkoaren artean dago.'},
   { stage:1, prompt:'Non dago Meka?', answer:'meka',tip:'Hiria Arabiar penintsularen mendebaldean dago.'},
   { stage:1, prompt:'Non dago Itsaso Gorria?', answer:'itsaso',tip:'Afrikaren eta Arabiar penintsularen arteko itsasoa da.'},
   { stage:1, prompt:'Non dago Persiako golkoa?', answer:'golkoa',tip:'Arabiar penintsularen ekialdean dago.'},
   { stage:2, prompt:'Artzaintza nomada egiten zuten.', answer:'barne',tip:'Zein tribu-motari dagokio deskribapena?'},
   { stage:2, prompt:'Sedentarioak ziren eta nekazaritzan eta merkataritzan aritzen ziren.', answer:'kosta',tip:'Zein tribu-motari dagokio deskribapena?'},
   { stage:2, prompt:'Erlijio fetixista zuten.', answer:'barne',tip:'Zein tribu-motari dagokio deskribapena?'},
   { stage:2, prompt:'Erlijio politeista zuten.', answer:'kosta',tip:'Zein tribu-motari dagokio deskribapena?'},
   { stage:3, prompt:'Zein zen goizeko izarraren jainkosa?', answer:'uzza',tip:'Aztertu hiru jainkosen irudiak.'},
   { stage:3, prompt:'Zein zen eguzkiaren jainkosa?', answer:'lat',tip:'Aztertu hiru jainkosen irudiak.'},
   { stage:3, prompt:'Zein zen denboraren jainkosa?', answer:'manat',tip:'Aztertu hiru jainkosen irudiak.'}
 ];
 const stageNames=['','Arabiako mapa','Tribuen bizimodua','Jainkosa aurreislamdarrak'];
 let st = null, timer=null;
 const key = 'islama-v4-puntuazioak';
 const esc = (s) => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const root = () => document.getElementById('arabia-v7');
 function launch(){
   if (root()) root().remove();
   const el = document.createElement('div');
   el.id='arabia-v7';
   el.innerHTML=`<main class="aa-app">
    <header class="aa-header"><button class="aa-home" data-action="home" aria-label="Hasierara itzuli">⌂ <span>HASIERA</span></button>
      <div class="aa-brand"><span class="aa-crescent">✦</span><div class="aa-brand-title">ARABIA EZAGUTZEN</div><small>ISLAMAREN ABENTURA · 01. JOKOA</small></div>
      <div class="aa-hud"><div class="aa-counter" id="aa-lives">♥ ♥ ♥</div><div class="aa-counter" id="aa-score">0 PUNTU</div><div class="aa-counter" id="aa-clock">04:00</div></div>
    </header>
    <section id="aa-start" class="aa-intro">
       <div class="aa-intro-art"></div><div class="aa-intro-content">
       <span class="aa-kicker">🏜️ 3 MAILA · 11 ERRONKA</span>
       <h1>Arabiar penintsularen sekretuak</h1><p>Bidaiatu antzinako Arabiara: ezagutu mapa, bereizi tribuen bizimoduak eta aurkitu jainkosa aurreislamdarrak.</p>
       <label for="aa-nick">Zure goitizena</label><input id="aa-nick" maxlength="18" placeholder="Adibidez: Izar7" autocomplete="off" />
       <button class="aa-primary" data-action="start">▶ ABIATU ABENTURA</button><p class="aa-error" id="aa-error"></p>
       <small>Proba lokala · Errekorrak ordenagailu honetan gordeko dira</small></div>
    </section>
    <section id="aa-playing" class="aa-playing" hidden>
      <div class="aa-chapters" id="aa-chapters"></div>
      <div class="aa-game-grid">
         <aside class="aa-quest"><div class="aa-quest-top"><span id="aa-level-number">1. MAILA</span><span id="aa-step-counter">1 / 11</span></div>
             <h2 id="aa-stage-title"></h2><div class="aa-ornament">✦ ── ✦</div><p class="aa-task-label">ERRONKA</p><h3 id="aa-prompt"></h3>
             <p id="aa-tip"></p><div class="aa-mini-illustration" id="aa-mini"></div>
             <div class="aa-feedback" id="aa-feedback" aria-live="polite">Aukeratu erantzuna irudian.</div>
             <div class="aa-progress-label"><span>AURRERAPENA</span><span id="aa-progress-n">0 / 11</span></div><div class="aa-progress"><span id="aa-progress-fill"></span></div>
         </aside>
         <section class="aa-play-area" id="aa-content"></section>
      </div>
      <footer class="aa-footer"><span>🏆 <strong>TOP 10</strong> · Proba lokala</span><div class="aa-ranklist" id="aa-rank"></div><button class="aa-info" data-action="home">MENURA ITZULI</button></footer>
    </section>
    <section id="aa-finish" class="aa-finish" hidden></section>
   </main>`;
   document.body.appendChild(el);
   document.body.style.overflow='hidden';
   const input=el.querySelector('#aa-nick');
   let lastName='';try{lastName=localStorage.getItem('arabia-v7-last-nickname')||''}catch{};input.value=lastName;
   el.addEventListener('click',onClick);
   el.addEventListener('dragstart',onDragStart);
   el.addEventListener('dragover',onDragOver);
   el.addEventListener('drop',onDrop);
   el.addEventListener('keydown',(e)=>{if(e.key==='Enter'&&e.target.id==='aa-nick')start();});
   updateRank();
 }
 function close(){stopTimer();const el=root();if(el)el.remove();document.body.style.overflow='';st=null;}
 function onClick(e){const action=e.target.closest('[data-action]');if(action){if(action.dataset.action==='home')close();if(action.dataset.action==='start')start();if(action.dataset.action==='retry')reset();return;}
    const button=e.target.closest('[data-answer]');if(button&&st&&!st.done&&!st.busy)choose(button.dataset.answer,button);
 }
 function start(){const el=root();if(!el)return;
   const name=el.querySelector('#aa-nick').value.trim();
   if(!/^[\p{L}\p{N}_ -]{2,18}$/u.test(name)){el.querySelector('#aa-error').textContent='Idatzi 2 eta 18 karaktere arteko goitizena.';return;}
   try{localStorage.setItem('arabia-v7-last-nickname',name)}catch{}
   st={name,step:0,correct:0,errors:0,lives:3,time:240,done:false,busy:false,history:[]};
   el.querySelector('#aa-start').hidden=true;el.querySelector('#aa-finish').hidden=true;el.querySelector('#aa-playing').hidden=false;
   render();updateHud();stopTimer();timer=setInterval(()=>{if(!st||st.done)return;st.time--;updateHud();if(st.time<=0)finish();},1000);
 }
 function reset(){let name=st?.name||'';if(!name){try{name=localStorage.getItem('arabia-v7-last-nickname')||''}catch{}}close();launch();root().querySelector('#aa-nick').value=name;start();}
 function stopTimer(){if(timer){clearInterval(timer);timer=null}}
 function calcScore(){if(!st)return 0;const ratio=st.correct/questions.length;return Math.min(1000,Math.round(750*ratio+250*ratio*st.time/240));}
 function updateHud(){if(!st)return;root().querySelector('#aa-lives').textContent='♥ '.repeat(st.lives)+'♡ '.repeat(3-st.lives);root().querySelector('#aa-score').textContent=calcScore().toLocaleString('eu-ES')+' PUNTU';root().querySelector('#aa-clock').textContent=String(Math.floor(st.time/60)).padStart(2,'0')+':'+String(st.time%60).padStart(2,'0');}
 function updateRank(){const el=root();if(!el)return;let scores={};try{scores=JSON.parse(localStorage.getItem(key)||'{}').arabia||{}}catch{};
   const rows=Object.values(scores).sort((a,b)=>b.score-a.score).slice(0,10);
   const r=el.querySelector('#aa-rank');if(!r)return;
   r.innerHTML=rows.length?rows.map((s,i)=>`<span><b>${i+1}.</b> ${esc(s.name)} <strong>${s.score.toLocaleString('eu-ES')}</strong></span>`).join(''):'<em>Oraindik ez dago errekorrik. Izan zaitez lehena!</em>';
 }
 function persist(){let scores={};try{scores=JSON.parse(localStorage.getItem(key)||'{}')}catch{};
   scores.arabia ||= {};const id=st.name.toLocaleLowerCase('eu');const score=calcScore();
   if(!scores.arabia[id]||scores.arabia[id].score<score)scores.arabia[id]={name:st.name,score,timestamp:Date.now()};
   try{localStorage.setItem(key,JSON.stringify(scores))}catch{}
 }
 function render(){if(!st)return;const q=questions[st.step];if(!q){finish();return;}
   const el=root();el.querySelector('#aa-level-number').textContent=q.stage+'. MAILA';el.querySelector('#aa-step-counter').textContent=(st.step+1)+' / '+questions.length;
   el.querySelector('#aa-stage-title').textContent=stageNames[q.stage];el.querySelector('#aa-prompt').textContent=q.prompt;el.querySelector('#aa-tip').textContent=q.tip;
   el.querySelector('#aa-feedback').className='aa-feedback';el.querySelector('#aa-feedback').textContent=q.stage===2?'Arrastatu txartela edo hautatu dagokion eszena.':'Aukeratu erantzuna irudian.';
   el.querySelector('#aa-progress-n').textContent=st.step+' / '+questions.length;
   el.querySelector('#aa-progress-fill').style.width=(100*st.step/questions.length)+'%';
   el.querySelector('#aa-chapters').innerHTML=[1,2,3].map((n)=>`<div class="aa-chapter ${n===q.stage?'on':n<q.stage?'done':''}"><b>0${n}</b><span>${esc(stageNames[n])}</span></div>`).join('');
   const mini=el.querySelector('#aa-mini');mini.innerHTML=q.stage===1?'🧭<span>MAPA INTERAKTIBOA</span>':q.stage===2?'🐪<span>BI BIZIMODU</span>':'✦<span>HIRU JAINKOSA</span>';
   if(q.stage===1)renderMap();if(q.stage===2)renderTribes();if(q.stage===3)renderGoddesses();updateHud();updateRank();
 }
 function renderMap(){const html=`<div class="aa-landscape aa-landscape-map" style="background-image:url('${image('aa-desert.webp')}')">
   <div class="aa-scenic-header"><span>🧭 LURRALDEA EZAGUTZEN</span><small>MAPAN KLIK EGIN</small></div>
   <div class="aa-map-frame"><div class="aa-map-image"><img src="${image('aa-map.webp')}" alt="Arabiar penintsularen mapa, 3. orrialdea" />
   <button class="aa-pin aa-pin-arabia" data-answer="arabia" aria-label="Arabiar penintsula"><span>◎</span></button>
   <button class="aa-pin aa-pin-meka" data-answer="meka" aria-label="Meka"><span>◎</span></button>
   <button class="aa-pin aa-pin-itsaso" data-answer="itsaso" aria-label="Itsaso Gorria"><span>◎</span></button>
   <button class="aa-pin aa-pin-golkoa" data-answer="golkoa" aria-label="Persiako golkoa"><span>◎</span></button>
   </div></div><div class="aa-landscape-caption">✦ ARABIAREN KOKAPENA ✦ <small>PDF · 3. orrialdea</small></div></div>`;
  root().querySelector('#aa-content').innerHTML=html;
 }
 function renderTribes(){root().querySelector('#aa-content').innerHTML=`<div class="aa-landscape aa-landscape-tribes" style="background-image:url('${image('aa-desert.webp')}')">
  <div class="aa-scenic-header"><span>🐪 TRIBUEN BIZIMODUA</span><small>HAUTATU EDO ARRASTATU</small></div>
  <div class="aa-two-scenes"><button class="aa-scene-card" data-answer="barne" aria-label="Barrualdekoak"><img src="${image('aa-nomads.webp')}" alt="Artzain nomadak basamortuan" /><strong>🏜️ BARRUALDEKOAK</strong><span>Basamortua eta artzaintza</span></button>
  <button class="aa-scene-card" data-answer="kosta" aria-label="Kostaldekoak"><img src="${image('aa-coast.webp')}" alt="Merkatariak itsasertzeko herri batean" /><strong>⛵ KOSTALDEKOAK</strong><span>Merkataritza eta nekazaritza</span></button></div>
  <div class="aa-drag-tray"><span>ARRASTATU EDO AUKERATU:</span><div draggable="true" class="aa-drag-token" data-token="1">${esc(questions[st.step].prompt)} <b>⇢</b></div></div></div>`;
 }
 function renderGoddesses(){root().querySelector('#aa-content').innerHTML=`<div class="aa-landscape aa-landscape-goddesses" style="background-image:url('${image('aa-desert.webp')}')"><div class="aa-scenic-header"><span>✦ JAINKOSA AURREISLAMDARRAK</span><small>IRUDIA HAUTATU</small></div>
   <div class="aa-goddess-grid">${[['uzza','Al-Uzza'],['lat','Al-Lat'],['manat','Manat']].map(([id,name])=>`<button class="aa-goddess" data-answer="${id}"><img src="${image('aa-'+id+'.webp')}" alt="${name}, 5. orrialdeko irudia"/><span>${name}</span></button>`).join('')}</div>
   <div class="aa-landscape-caption">✦ JAINKOSAK ETA HAIEN EZAUGARRIAK ✦ <small>PDF · 5. orrialdea</small></div></div>`;
 }
 function onDragStart(e){if(e.target.matches('.aa-drag-token'))e.dataTransfer.setData('text/plain','aa-token')}
 function onDragOver(e){if(e.target.closest('.aa-scene-card'))e.preventDefault()}
 function onDrop(e){const card=e.target.closest('.aa-scene-card');if(card&&st&&!st.busy&&st.step>=4&&st.step<8){e.preventDefault();choose(card.dataset.answer,card)}}
 function choose(answer,button){if(!st||st.busy||st.done)return;const q=questions[st.step];st.busy=true;let ok=answer===q.answer;
    if(ok){st.correct++;root().querySelector('#aa-feedback').className='aa-feedback success';root().querySelector('#aa-feedback').textContent='Bikain! Erantzun zuzena! +Puntuak';}
    else{st.errors++;st.lives=Math.max(0,st.lives-1);root().querySelector('#aa-feedback').className='aa-feedback mistake';root().querySelector('#aa-feedback').textContent='Ez da zuzena. Saiatu hurrengo erronkan!';}
    button.classList.add(ok?'aa-correct':'aa-wrong');st.history.push(ok);updateHud();
    root().querySelectorAll('[data-answer]').forEach(b=>{b.disabled=true;});
    setTimeout(()=>{if(!st||st.done)return;st.step++;st.busy=false;if(st.lives===0||st.step===questions.length)finish();else render();},850);
 }
 function finish(){if(!st||st.done)return;st.done=true;stopTimer();persist();const el=root();const score=calcScore();el.querySelector('#aa-playing').hidden=true;el.querySelector('#aa-finish').hidden=false;
   el.querySelector('#aa-finish').innerHTML=`<div class="aa-final-wrap" style="background-image:url('${image('aa-desert.webp')}')"><div class="aa-final-card"><span>🏆</span><h2>${st.lives>0&&st.step>=questions.length?'ABENTURA OSATUTA!':'ABENTURA AMAITU DA'}</h2>
    <p>${esc(st.name)}, zure emaitza:</p><strong>${score.toLocaleString('eu-ES')} PUNTU</strong><p>${st.correct} / ${questions.length} erantzun zuzen</p><small>TOP 10 lokala eguneratu da. Ez da oraindik partekatutako online sailkapena.</small>
    <div class="aa-final-buttons"><button class="aa-primary" data-action="retry">↻ BERRIRO JOLASTU</button><button class="aa-primary aa-secondary" data-action="home">⌂ MENURA ITZULI</button></div></div></div>`;
 }
 window.ARABIA_V7={launch,close,questions:()=>questions,getState:()=>st&&({step:st.step,lives:st.lives,score:calcScore(),done:st.done}),testStart:(name='Proba')=>{launch();root().querySelector('#aa-nick').value=name;start()}};
})();

